-- Has account_id + user_id on remote; scope by account membership + app access
CREATE POLICY availability_slots_select ON availability_slots FOR SELECT TO authenticated
  USING (
    user_id = auth.uid()
    OR (account_id IS NOT NULL AND is_account_member(account_id) AND has_app_access(account_id, app_id))
  );
CREATE POLICY availability_slots_insert ON availability_slots FOR INSERT TO authenticated
  WITH CHECK (app_id = get_app_id('rankora') AND auth.uid() IS NOT NULL);
CREATE POLICY availability_slots_update ON availability_slots FOR UPDATE TO authenticated
  USING (
