  FOR EACH ROW EXECUTE FUNCTION set_rankora_app_id();


-- ────────────────────────────────────────────────────────────────────────────
-- PART 3: Fix 2 remaining gap tables — add app_id
-- ────────────────────────────────────────────────────────────────────────────

-- rankora_platform_config (PK is account_id, no id column)
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'rankora_platform_config' AND column_name = 'app_id'
  ) THEN
    ALTER TABLE rankora_platform_config ADD COLUMN app_id uuid REFERENCES apps(id) DEFAULT get_app_id('rankora');
    UPDATE rankora_platform_config SET app_id = get_app_id('rankora') WHERE app_id IS NULL;
    ALTER TABLE rankora_platform_config ALTER COLUMN app_id SET NOT NULL;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_rankora_platform_config_app ON rankora_platform_config(app_id);

CREATE TRIGGER trg_rankora_platform_config_app_id BEFORE INSERT ON rankora_platform_config
  FOR EACH ROW EXECUTE FUNCTION set_rankora_app_id();

-- email_ingest_logs
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'email_ingest_logs' AND column_name = 'app_id'
  ) THEN
    ALTER TABLE email_ingest_logs ADD COLUMN app_id uuid REFERENCES apps(id) DEFAULT get_app_id('rankora');
    UPDATE email_ingest_logs SET app_id = get_app_id('rankora') WHERE app_id IS NULL;
    ALTER TABLE email_ingest_logs ALTER COLUMN app_id SET NOT NULL;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_email_ingest_logs_account_app ON email_ingest_logs(account_id, app_id);

CREATE TRIGGER trg_email_ingest_logs_app_id BEFORE INSERT ON email_ingest_logs
  FOR EACH ROW EXECUTE FUNCTION set_rankora_app_id();

-- RLS for email_ingest_logs (was missing proper policies)
ALTER TABLE email_ingest_logs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS email_ingest_logs_select ON email_ingest_logs;
DROP POLICY IF EXISTS email_ingest_logs_insert ON email_ingest_logs;
DROP POLICY IF EXISTS email_ingest_logs_all ON email_ingest_logs;

CREATE POLICY email_ingest_logs_select ON email_ingest_logs FOR SELECT TO authenticated
  USING (
    (user_id IS NOT NULL AND user_id = auth.uid())
    OR (account_id IS NOT NULL AND is_account_member(account_id) AND has_app_access(account_id, app_id))
  );
CREATE POLICY email_ingest_logs_insert ON email_ingest_logs FOR INSERT TO authenticated
  WITH CHECK (app_id = get_app_id('rankora'));


