    culture_title       = NEW.culture_title,
    culture_description = NEW.culture_description,
    benefits_json       = NEW.benefits_json,
    testimonials_json   = NEW.testimonials_json,
    social_links_json   = NEW.social_links_json,
    meta_title          = NEW.meta_title,
    meta_description    = NEW.meta_description,
    is_published        = COALESCE(NEW.is_published, is_published)
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION career_page_config_delete_trigger()
RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER AS $$
