  return useQuery<OutreachEvent[]>({
    queryKey: ["outreach-history", resumeId],
    queryFn: async () => {
      if (!resumeId) return [];

      const [emailsRes, smsRes] = await Promise.all([
        (supabase as any)
          .from("outreach_log")
          .select("id, type, to_address, subject, status, sent_at, user_id")
          .eq("resume_id", resumeId)
          .order("sent_at", { ascending: false }),
        (supabase as any)
          .from("sms_logs")
          .select("id, to_phone, message, status, created_at, user_id, error")
          .eq("resume_id", resumeId)
          .order("created_at", { ascending: false }),
      ]);

      const emails = ((emailsRes.data ?? []) as OutreachLogRow[]).map(fromOutreachLog);
      const sms = ((smsRes.data ?? []) as SmsLogRow[]).map(fromSmsLog);

      const merged = [...emails, ...sms];
      merged.sort((a, b) => (a.sent_at < b.sent_at ? 1 : -1));
      return merged;
    },
    enabled: !!resumeId,
    staleTime: 60_000,
  });
}

