-- ============================================================================
-- 20260420000021_agency_placements_schema_extension.sql
--
-- agency_placements was created in 0006 as a stub (id, account_id, team_id,
-- mandate_id, status, created_at, updated_at). The frontend hook expects a
-- full placement record: client_id FK, candidate details, salary, fees,
-- guarantee tracking. Every load of the Agency tab threw because the
-- SELECT referenced non-existent columns and an inferrable join.
-- ============================================================================


-- ────────────────────────────────────────────────────────────────────────────
-- Part 1: Extend agency_placements with the columns the UI needs
-- ────────────────────────────────────────────────────────────────────────────

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS client_id uuid REFERENCES agency_clients(id) ON DELETE SET NULL;

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS candidate_name text;

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS candidate_email text;

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS start_date date;

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS salary numeric;

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS fee_amount numeric;

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS guarantee_days integer;

ALTER TABLE agency_placements
  ADD COLUMN IF NOT EXISTS guarantee_expires_at timestamptz;

-- Backfill client_id from mandate for any existing rows
UPDATE agency_placements p
SET client_id = m.client_id
FROM agency_mandates m
WHERE p.mandate_id = m.id AND p.client_id IS NULL;


-- ────────────────────────────────────────────────────────────────────────────
-- Part 2: agency_mandates.job_title alias (frontend queries `job_title` but
-- table column is `title`). Add a sync trigger so both stay in lockstep.
-- ────────────────────────────────────────────────────────────────────────────

ALTER TABLE agency_mandates
  ADD COLUMN IF NOT EXISTS job_title text;

-- Backfill
UPDATE agency_mandates SET job_title = title WHERE job_title IS NULL;

CREATE OR REPLACE FUNCTION agency_mandates_sync_job_title()
RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.job_title IS NULL AND NEW.title IS NOT NULL THEN
    NEW.job_title := NEW.title;
  ELSIF NEW.title IS NULL AND NEW.job_title IS NOT NULL THEN
    NEW.title := NEW.job_title;
  ELSIF TG_OP = 'UPDATE' AND NEW.job_title IS DISTINCT FROM OLD.job_title
        AND NEW.title IS NOT DISTINCT FROM OLD.title THEN
    NEW.title := NEW.job_title;
  ELSIF TG_OP = 'UPDATE' AND NEW.title IS DISTINCT FROM OLD.title
        AND NEW.job_title IS NOT DISTINCT FROM OLD.job_title THEN
    NEW.job_title := NEW.title;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS agency_mandates_sync_job_title_trg ON agency_mandates;
CREATE TRIGGER agency_mandates_sync_job_title_trg
  BEFORE INSERT OR UPDATE ON agency_mandates
  FOR EACH ROW EXECUTE FUNCTION agency_mandates_sync_job_title();


-- ────────────────────────────────────────────────────────────────────────────
-- Part 3: Indexes for the new FK + query paths
-- ────────────────────────────────────────────────────────────────────────────

CREATE INDEX IF NOT EXISTS idx_agency_placements_client ON agency_placements(client_id);
CREATE INDEX IF NOT EXISTS idx_agency_placements_team_created
  ON agency_placements(team_id, created_at DESC);

