"use client";

import type { LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";

interface AdminPageHeaderProps {
  title: string;
  description?: string;
  icon?: LucideIcon;
  /** Right-aligned content: action buttons, filters, date picker, etc. */
  actions?: React.ReactNode;
  /** Extra content below the title/description row (tabs, segmented controls). */
  children?: React.ReactNode;
  className?: string;
}

/**
 * Shared page header for every admin tab.
 *
 * Mirrors the live-app section header rhythm:
 * - h1 text-[22px] font-semibold (brand density; sits between text-xl and text-2xl)
 * - description text-sm text-muted-foreground
 * - optional icon in a compact rounded badge matching live-app stat cards
 * - actions slot on the right for buttons/filters
 * - thin 1px divider below the header when there are no child tabs
 */
const AdminPageHeader = ({
  title,
  description,
  icon: Icon,
  actions,
  children,
  className,
}: AdminPageHeaderProps) => {
  return (
    <div className={cn("flex flex-col gap-4 pb-5 mb-5 border-b border-border/60", className)}>
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="flex items-start gap-3 min-w-0">
          {Icon ? (
            <div className="h-9 w-9 shrink-0 rounded-lg bg-primary/10 text-primary flex items-center justify-center">
              <Icon className="h-[18px] w-[18px]" />
            </div>
          ) : null}
          <div className="min-w-0">
            <h1 className="text-[22px] font-semibold text-foreground tracking-tight leading-tight truncate">
              {title}
            </h1>
            {description ? (
              <p className="text-sm text-muted-foreground mt-0.5 leading-snug">
                {description}
              </p>
            ) : null}
          </div>
        </div>
        {actions ? (
          <div className="flex items-center gap-2 flex-wrap shrink-0">{actions}</div>
        ) : null}
      </div>
      {children}
    </div>
  );
};

export default AdminPageHeader;

