interface AdminSidebarProps {
  active: AdminSection;
  onSelect: (section: AdminSection) => void;
}

// ─── Component ──────────────────────────────────────────────────────────────
//
// Secondary left rail inside the admin content pane. Matches the live-app
// JobSidebar type-scale exactly:
//   - text-[10.5px] uppercase section labels
//   - text-[13px] font-medium nav items, h-8, gap-2.5, px-2
//   - bg-sidebar-accent for the active row
//   - h-4 w-4 icons with 16px left edge alignment
//
// Renders as a sticky 224px column so it stays visible while the content
// scrolls. The outer card already has border + shadow; we only need the
// right-side divider to separate rail from content.

const AdminSidebar = ({ active, onSelect }: AdminSidebarProps) => {
  return (
    <aside className="w-56 shrink-0 border-r border-border/60 overflow-y-auto bg-background">
      <nav className="flex flex-col px-2 py-3">
        {sectionGroups.map((group, gi) => (
          <div key={group.label} className={cn(gi > 0 && "mt-3")}>
            <p className="px-2 pt-1 pb-1.5 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/70 select-none">
              {group.label}
            </p>
            <div className="flex flex-col gap-0.5">
              {group.items.map(({ key, label, icon: Icon }) => {
                const isActive = active === key;
                return (
                  <button
                    key={key}
                    onClick={() => onSelect(key)}
                    className={cn(
                      "flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full text-left",
                      isActive
                        ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold"
                        : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60",
                    )}
                  >
                    <Icon
                      className={cn(
                        "h-4 w-4 shrink-0",
                        isActive ? "text-foreground" : "text-muted-foreground",
                      )}
                    />
                    {label}
                  </button>
                );
              })}
            </div>
          </div>
        ))}
      </nav>
    </aside>
  );
};

export default AdminSidebar;

