"use client";

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import {
  Users, Briefcase, FileText, Coins, DollarSign, TrendingUp, UserCheck, BarChart3,
  RefreshCw, CalendarIcon, Mail, Inbox, ArrowRight,
} from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, LineChart, Line } from "recharts";
import { format, subDays } from "date-fns";
import { cn } from "@/lib/utils";
import type { DateRange } from "react-day-picker";

interface StatsData {
  total_users: number;
  total_jobs: number;
  total_resumes: number;
  total_credits_used: number;
  total_revenue: number;
  mrr_30d: number;
  conversion_rate: number;
  active_users_7d: number;
  active_users_30d: number;
  avg_resumes_per_job: number;
  resumes_today: number;
  resumes_week: number;
  resumes_month: number;
  daily_chart: { date: string; credits: number; jobs: number; signups: number; revenue: number }[];
}

const PRESETS = [
  { label: "7 days", days: 7 },
  { label: "30 days", days: 30 },
  { label: "90 days", days: 90 },
  { label: "1 year", days: 365 },
] as const;

const DashboardTab = () => {
  const qc = useQueryClient();
  const [dateRange, setDateRange] = useState<DateRange | undefined>({
    from: subDays(new Date(), 30),
    to: new Date(),
  });
  const [activePreset, setActivePreset] = useState<number>(30);

  const fromISO = dateRange?.from?.toISOString().slice(0, 10);
  const toISO = dateRange?.to?.toISOString().slice(0, 10);

  const { data: stats, isLoading, isFetching } = useQuery({
    queryKey: ["admin_stats", fromISO, toISO],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-stats", {
        body: { from: fromISO, to: toISO },
      });
      if (error) throw error;
      return data as StatsData;
    },
  });

  const { data: emailConfig } = useQuery({
    queryKey: ["admin_email_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("email_ingestion_enabled").limit(1).single();
      if (error) throw error;
      return data;
    },
    staleTime: 5 * 60 * 1000,
  });

  const selectPreset = (days: number) => {
    setActivePreset(days);
    setDateRange({ from: subDays(new Date(), days), to: new Date() });
  };

  const handleRangeSelect = (range: DateRange | undefined) => {
    setDateRange(range);
    setActivePreset(0); // clear preset when custom selected
  };

  const rangeDays = dateRange?.from && dateRange?.to
    ? Math.ceil((dateRange.to.getTime() - dateRange.from.getTime()) / (1000 * 60 * 60 * 24))
    : 30;
  const rangeLabel = activePreset
    ? PRESETS.find(p => p.days === activePreset)?.label ?? `${rangeDays}d`
    : dateRange?.from && dateRange?.to
      ? `${format(dateRange.from, "MMM d")} – ${format(dateRange.to, "MMM d, yyyy")}`
      : "30 days";

  const cards = [
    { label: "Total Users", value: stats?.total_users, icon: Users, color: "text-blue-500" },
