"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { ChevronLeft, ChevronRight, Download, ScrollText } from "lucide-react";
import { exportToCSV } from "@/lib/csvExport";
import AdminPageHeader from "@/components/admin/AdminPageHeader";

const PAGE_SIZE = 20;

const UsageLogsTab = () => {
  const [page, setPage] = useState(0);

  // Fetch user email map
  const { data: userMap } = useQuery({
    queryKey: ["admin_users"],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
      if (error) throw error;
      if (!Array.isArray(data)) throw new Error(data?.error || "Failed to load users");
      const map: Record<string, string> = {};
      data.forEach((u: any) => { map[u.id] = u.email; });
      return map;
    },
    staleTime: 5 * 60 * 1000,
  });

  const { data } = useQuery({
    queryKey: ["admin_usage_logs", page],
    queryFn: async () => {
      const from = page * PAGE_SIZE;
      const to = from + PAGE_SIZE - 1;
      const { data, error, count } = await supabase
        .from("usage_logs")
        .select("*", { count: "exact" })
        .order("created_at", { ascending: false })
        .range(from, to);
      if (error) throw error;
      return { logs: data, total: count ?? 0 };
    },
  });

  const totalPages = Math.ceil((data?.total ?? 0) / PAGE_SIZE);

  const handleExport = () => {
    if (!data?.logs?.length) return;
    const rows = data.logs.map((l: any) => ({
      user: userMap?.[l.user_id] || l.user_id,
      job_id: l.job_id || "",
      credits_used: l.credits_used,
      date: new Date(l.created_at).toISOString(),
    }));
    exportToCSV(rows, "usage-logs");
  };

  return (
    <div className="space-y-6">
    <AdminPageHeader
      title="Usage Logs"
      description="Every credit-consuming action, per user and per job."
      icon={ScrollText}
      actions={
        <>
          <Button variant="outline" size="sm" onClick={handleExport} disabled={!data?.logs?.length} className="gap-1.5">
            <Download className="h-3.5 w-3.5" /> CSV
          </Button>
          <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <span>Page {page + 1} of {Math.max(totalPages, 1)}</span>
            <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
              <ChevronLeft className="h-3.5 w-3.5" />
            </Button>
            <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
              <ChevronRight className="h-3.5 w-3.5" />
            </Button>
          </div>
        </>
      }
    />
    <Card className="border-border/60 shadow-sm">
      <CardHeader className="sr-only">
        <CardTitle>Usage Logs Table</CardTitle>
      </CardHeader>
      <CardContent className="p-0">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>User</TableHead>
              <TableHead>Job ID</TableHead>
              <TableHead>Credits Used</TableHead>
              <TableHead>Date</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {data?.logs?.map((l: any) => (
              <TableRow key={l.id}>
                <TableCell className="text-sm" title={l.user_id}>
                  {userMap?.[l.user_id] || l.user_id?.slice(0, 8) + "…"}
                </TableCell>
                <TableCell className="font-mono text-xs">{l.job_id?.slice(0, 8) ?? "—"}</TableCell>
                <TableCell>{l.credits_used}</TableCell>
                <TableCell className="text-sm">{new Date(l.created_at).toLocaleString()}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
};

export default UsageLogsTab;

