/**
 * Multi-region currency utilities for the billing page.
 *
 * Supports INR, USD, GBP, EUR. Each currency stores prices in MINOR units
 * (paise / cents / pence / cents) per the standard `prices_json` shape on
 * the `plans` table:
 *   { "INR": 379900, "USD": 4900, "GBP": 3900, "EUR": 4500 }
 *
 * Geo-detect runs once on first paint, persists to localStorage, and is
 * user-overridable via the CurrencySwitcher.
 */

export type Currency = "INR" | "USD" | "GBP" | "EUR";

export const CURRENCY_OPTIONS: { code: Currency; symbol: string; label: string }[] = [
  { code: "INR", symbol: "₹", label: "INR" },
  { code: "USD", symbol: "$", label: "USD" },
  { code: "GBP", symbol: "£", label: "GBP" },
  { code: "EUR", symbol: "€", label: "EUR" },
];

const STORAGE_KEY = "rankora:billing-currency";

/**
 * Detect the user's currency from browser locale on first paint.
 * Order of resolution:
 *   1. localStorage override (user clicked a different currency before)
 *   2. navigator.language → currency mapping
 *   3. Fallback to USD
 */
export function detectCurrency(): Currency {
  if (typeof window === "undefined") return "USD";

  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored && isCurrency(stored)) return stored;
  } catch {
    /* localStorage unavailable */
  }

  const lang = typeof navigator !== "undefined" ? navigator.language?.toLowerCase() ?? "" : "";

  // India: hi, hi-IN, en-IN, gu, ta, te, bn, mr, kn, ml, pa, ur
  if (
    lang.includes("-in") ||
    lang.startsWith("hi") ||
    lang.startsWith("gu") ||
    lang.startsWith("ta") ||
    lang.startsWith("te") ||
    lang.startsWith("bn") ||
    lang.startsWith("mr") ||
    lang.startsWith("kn") ||
    lang.startsWith("ml") ||
    lang.startsWith("pa")
  ) {
    return "INR";
  }

  // UK
  if (lang.includes("-gb") || lang === "en-uk") return "GBP";

  // Eurozone — common locales
  if (
    lang.startsWith("de") ||
    lang.startsWith("fr") ||
    lang.startsWith("es") ||
    lang.startsWith("it") ||
    lang.startsWith("nl") ||
    lang.startsWith("pt") ||
    lang.includes("-de") ||
    lang.includes("-fr") ||
    lang.includes("-es") ||
    lang.includes("-it") ||
    lang.includes("-nl") ||
    lang.includes("-ie") ||
    lang.includes("-at") ||
    lang.includes("-be") ||
    lang.includes("-fi")
  ) {
    return "EUR";
  }

  return "USD";
}

export function persistCurrency(currency: Currency): void {
  try {
    localStorage.setItem(STORAGE_KEY, currency);
  } catch {
    /* storage unavailable; fall back to in-memory only */
  }
}

function isCurrency(value: string): value is Currency {
  return value === "INR" || value === "USD" || value === "GBP" || value === "EUR";
}

/**
 * Format a minor-unit amount in the given currency, using the matching
 * locale's grouping and symbol.
 *
 * Examples:
 *   formatPrice(379900, "INR")  → "₹3,799"
 *   formatPrice(4900, "USD")    → "$49"
 *   formatPrice(0, "USD")       → "$0"
 *   formatPrice(46800, "USD")   → "$468"
 */
export function formatPrice(amountMinor: number, currency: Currency): string {
  const major = amountMinor / 100;
  const locale = currency === "INR" ? "en-IN" : currency === "GBP" ? "en-GB" : currency === "EUR" ? "en-IE" : "en-US";

  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(major);
}

/**
 * Read the price for a currency from a `prices_json` blob with safe fallback
 * to USD if the chosen currency is missing.
 */
export function priceFromBlob(
  prices: Record<string, number> | null | undefined,
  currency: Currency,
): number {
  if (!prices) return 0;
  const v = prices[currency];
  if (typeof v === "number" && v >= 0) return v;
  // Fallback chain: USD → first available → 0
  if (typeof prices.USD === "number") return prices.USD;
  const first = Object.values(prices).find((n) => typeof n === "number");
  return typeof first === "number" ? first : 0;
}

/**
 * Compute annual savings percentage given a monthly price and an annual
 * (per-year total) price, both in the same currency in minor units.
 *
 * Returns 0 if either input is missing or non-positive.
 */
export function annualSavingsPercent(monthlyMinor: number, annualMinor: number): number {
  if (!monthlyMinor || !annualMinor) return 0;
  const yearlyAtMonthly = monthlyMinor * 12;
  if (yearlyAtMonthly <= annualMinor) return 0;
  return Math.round(((yearlyAtMonthly - annualMinor) / yearlyAtMonthly) * 100);
}

