"use client";

import { CURRENCY_OPTIONS, type Currency } from "@/lib/currency";
import { cn } from "@/lib/utils";

interface CurrencySwitcherProps {
  value: Currency;
  onChange: (currency: Currency) => void;
  className?: string;
}

/**
 * Compact 4-button currency selector. Same pattern as the AppHeader's theme
 * group — single-row segmented control with active highlight.
 */
const CurrencySwitcher = ({ value, onChange, className }: CurrencySwitcherProps) => {
  return (
    <div
      className={cn(
        "flex items-center rounded-lg border border-border bg-muted/40 p-0.5",
        className,
      )}
      role="radiogroup"
      aria-label="Display currency"
    >
      {CURRENCY_OPTIONS.map(({ code, symbol, label }) => {
        const isActive = value === code;
        return (
          <button
            key={code}
            type="button"
            role="radio"
            aria-checked={isActive}
            onClick={() => onChange(code)}
            className={cn(
              "px-2.5 h-7 rounded-md text-[12px] font-medium transition-colors flex items-center gap-1.5",
              isActive
                ? "bg-background shadow-sm text-foreground"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            <span className="font-semibold">{symbol}</span>
            <span>{label}</span>
          </button>
        );
      })}
    </div>
  );
};

export default CurrencySwitcher;

