"use client";

import { Check, Loader2, Sparkles, ArrowRight, RefreshCw } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  formatPrice,
  priceFromBlob,
  annualSavingsPercent,
  type Currency,
} from "@/lib/currency";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface PlanLimits {
  active_jobs?: number;
  cvs_per_month?: number;
  team_members?: number;
  talent_pool?: number;
  ai_credits_per_month?: number;
}

export interface PlanRow {
  id: string;
  slug: string;
  name: string;
  description: string | null;
  billing_type: string;
  interval: "month" | "year" | null;
  audience_label: string | null;
  is_popular: boolean;
  feature_highlights: string[];
  prices_json: Record<string, number>;
  limits_json: PlanLimits;
}

interface PlanCardProps {
  plan: PlanRow;
  /** The matching monthly plan when this card is annual — used to compute savings %. Optional. */
  monthlyCounterpart?: PlanRow | null;
  currency: Currency;
  /** Selected billing cadence in the parent. */
  cadence: "monthly" | "annual";
  isCurrent: boolean;
  isFree: boolean;
  buying: boolean;
  downgrading: boolean;
  onSubscribe: () => void;
  onSwitchToFree: () => void;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function formatLimit(value: number | undefined): string {
  if (value === undefined || value === null) return "—";
  if (value < 0) return "Unlimited";
  return value.toLocaleString();
}

const LIMIT_LABELS: { key: keyof PlanLimits; label: string }[] = [
  { key: "active_jobs", label: "Active Jobs" },
  { key: "cvs_per_month", label: "CVs / month" },
  { key: "team_members", label: "Team Members" },
  { key: "talent_pool", label: "Talent Pool" },
];

// ─── Component ────────────────────────────────────────────────────────────────

const PlanCard = ({
  plan,
  monthlyCounterpart,
  currency,
  cadence,
  isCurrent,
  isFree,
  buying,
  downgrading,
  onSubscribe,
  onSwitchToFree,
}: PlanCardProps) => {
  const priceMinor = priceFromBlob(plan.prices_json, currency);

  // For annual plans, show the per-month equivalent ("₹2,999/mo, billed yearly as ₹35,988")
  const isAnnual = cadence === "annual" && plan.interval === "year";
  const displayMinor = isAnnual ? Math.round(priceMinor / 12) : priceMinor;

  const annualSavings =
    isAnnual && monthlyCounterpart
      ? annualSavingsPercent(priceFromBlob(monthlyCounterpart.prices_json, currency), priceMinor)
      : 0;

  const periodLabel = isFree
    ? "Free forever"
    : plan.interval === "year"
      ? "/mo, billed yearly"
      : "/month";

  return (
    <div
      className={cn(
        "relative flex flex-col rounded-xl border bg-card transition-all p-5",
        isCurrent
          ? "border-primary/50 ring-2 ring-primary/20"
          : plan.is_popular
            ? "border-primary/40 shadow-md"
            : "border-border/60 shadow-sm hover:border-border",
      )}
    >
      {/* Top badge: Popular OR Current */}
      {plan.is_popular && !isCurrent && (
        <span className="absolute -top-2.5 left-4">
          <Badge className="text-[10px] px-2 h-5 bg-primary text-primary-foreground gap-1">
            <Sparkles className="h-2.5 w-2.5" />
            Most Popular
          </Badge>
        </span>
      )}
      {isCurrent && (
        <span className="absolute -top-2.5 left-4">
          <Badge className="text-[10px] px-2 h-5 bg-primary text-primary-foreground gap-1">
            <Check className="h-2.5 w-2.5" />
            Current Plan
          </Badge>
        </span>
      )}

      {/* Header */}
      <div className="mb-4">
        <p className="text-sm font-semibold text-foreground">{plan.name}</p>
        {plan.audience_label && (
          <p className="text-[11px] text-muted-foreground mt-0.5">{plan.audience_label}</p>
        )}
      </div>

      {/* Price */}
      <div className="mb-4">
        <div className="flex items-baseline gap-1">
          <span className="text-3xl font-bold text-foreground tracking-tight">
            {formatPrice(displayMinor, currency)}
          </span>
          {!isFree && (
            <span className="text-xs text-muted-foreground">{periodLabel}</span>
          )}
          {isFree && <span className="text-xs text-muted-foreground ml-1">forever</span>}
        </div>
        {isAnnual && annualSavings > 0 && (
          <p className="text-[11px] text-emerald-600 font-medium mt-1">
            Save {annualSavings}% — billed as {formatPrice(priceMinor, currency)} / year
          </p>
        )}
        {!isFree && !isAnnual && (
          <p className="text-[11px] text-muted-foreground mt-1">Billed monthly. Cancel anytime.</p>
        )}
      </div>

      {/* Limits grid */}
      <div className="rounded-lg border border-border/60 bg-muted/30 p-3 mb-4">
        <ul className="grid grid-cols-2 gap-x-3 gap-y-2">
          {LIMIT_LABELS.map(({ key, label }) => (
            <li key={key} className="flex flex-col">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground/70 font-medium">
                {label}
              </span>
              <span className="text-[13px] font-semibold text-foreground tabular-nums">
                {formatLimit(plan.limits_json?.[key])}
              </span>
            </li>
          ))}
        </ul>
      </div>

      {/* Feature highlights */}
      <ul className="space-y-1.5 flex-1 mb-5">
        {plan.feature_highlights.map((f) => (
          <li key={f} className="flex items-start gap-2 text-[12px] text-muted-foreground leading-snug">
            <Check className="h-3.5 w-3.5 text-primary mt-0.5 shrink-0" />
            <span>{f}</span>
          </li>
        ))}
      </ul>

      {/* CTA */}
      {isCurrent ? (
        <div className="h-9 flex items-center justify-center rounded-md bg-muted/50">
          <span className="text-[11px] font-medium text-muted-foreground">Your current plan</span>
        </div>
      ) : isFree ? (
        <Button
          variant="outline"
          size="sm"
          className="w-full h-9 text-xs gap-1.5 border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
          onClick={onSwitchToFree}
          disabled={downgrading}
        >
          {downgrading ? <Loader2 className="h-3 w-3 animate-spin" /> : <RefreshCw className="h-3 w-3" />}
          Switch to Free
        </Button>
      ) : (
        <Button
          size="sm"
          className="w-full h-9 text-xs gap-1.5"
          onClick={onSubscribe}
          disabled={buying}
        >
          {buying ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <>
              {plan.is_popular ? "Start with Growth" : `Choose ${plan.name}`}
              <ArrowRight className="h-3 w-3" />
            </>
          )}
        </Button>
      )}
    </div>
  );
};

export default PlanCard;

