import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Card, CardContent } from "@/components/ui/card";

const FAQS: { q: string; a: string }[] = [
  {
    q: "Can I cancel anytime?",
    a: "Yes. Cancel auto-renewal whenever you want from the Billing page. Your plan stays active until the end of the current billing period; after that you move to Free. Remaining credits are preserved.",
  },
  {
    q: "Is there a money-back guarantee?",
    a: "Yes — 14-day money-back on your first paid month, no questions asked. Email billing@rankora.co and we'll process the refund within 3 working days.",
  },
  {
    q: "How does GST work for India?",
    a: "Indian customers see prices in ₹ on the Billing page. 18% GST is added at checkout as a separate line item, so you can claim input tax credit. We issue a GST-compliant invoice for every payment.",
  },
  {
    q: "Can I switch plans mid-cycle?",
    a: "Upgrades take effect immediately and we prorate the difference against your next bill. Downgrades take effect at the end of the current billing period so you don't lose features you've already paid for.",
  },
  {
    q: "Do credits roll over?",
    a: "AI credits reset every billing period (monthly or annually based on your plan). Bonus credits granted by support never expire. Talent pool storage is unlimited on every plan and never deletes.",
  },
  {
    q: "Do you charge per user?",
    a: "No. Every paid plan includes unlimited team members. Add as many recruiters, hiring managers, and interviewers as you need without your bill changing.",
  },
  {
    q: "Can I use my own domain on the career page?",
    a: "Custom domains are on our Q1 2026 roadmap. Today every career page lives at rankora.co/careers/[your-slug]. White-label branding (logo, colors, typography) is available on Agency.",
  },
  {
    q: "Who owns the candidate data?",
    a: "You do. Resumes, notes, scores, and pipeline data are yours. We provide a one-click GDPR data export per candidate from the admin panel and a full account export on request.",
  },
];

const PricingFAQ = () => {
  return (
    <section>
      <h2 className="text-lg font-semibold text-foreground mb-1">Frequently asked questions</h2>
      <p className="text-sm text-muted-foreground mb-4">
        Still have questions?{" "}
        <a href="mailto:billing@rankora.co" className="text-primary hover:underline">
          billing@rankora.co
        </a>{" "}
        — we reply within one business day.
      </p>

      <Card className="border-border/60 shadow-sm">
        <CardContent className="p-2">
          <Accordion type="single" collapsible className="w-full">
            {FAQS.map((faq, i) => (
              <AccordionItem
                key={faq.q}
                value={`faq-${i}`}
                className="border-border/60 last:border-0"
              >
                <AccordionTrigger className="text-sm text-left font-medium hover:no-underline px-3 py-3">
                  {faq.q}
                </AccordionTrigger>
                <AccordionContent className="text-sm text-muted-foreground leading-relaxed px-3 pb-4">
                  {faq.a}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </CardContent>
      </Card>
    </section>
  );
};

export default PricingFAQ;

