"use client";

import { useState } from "react";
import {
  Briefcase,
  Users,
  Clock,
  TrendingUp,
  AlertCircle,
  ChevronDown,
} from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { TimeToHireCard } from "@/components/analytics/TimeToHireCard";
import { StageFunnel } from "@/components/analytics/StageFunnel";
import { ScoreHistogram } from "@/components/analytics/ScoreHistogram";
import { ActivityHeatmap } from "@/components/analytics/ActivityHeatmap";
import { TopJobsTable } from "@/components/analytics/TopJobsTable";
import { ProductivityGrid } from "@/components/analytics/ProductivityGrid";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { useProductivityStats } from "@/hooks/useAnalytics";

// ─── Types ────────────────────────────────────────────────────────────────────

const RANGE_OPTIONS = ["Last 30 days", "Last 90 days", "Last 6 months", "All time"] as const;
type RangeOption = (typeof RANGE_OPTIONS)[number];

// ─── Stat card ────────────────────────────────────────────────────────────────

interface StatCardProps {
  title: string;
  value: string;
  sub?: string;
  icon: React.ReactNode;
  loading?: boolean;
}

function StatCard({ title, value, sub, icon, loading }: StatCardProps) {
  if (loading) {
    return (
      <Card className="border border-border/60 shadow-sm">
        <CardContent className="pt-5 pb-4 px-5">
          <Skeleton className="h-4 w-28 mb-3" />
          <Skeleton className="h-8 w-20 mb-1.5" />
          <Skeleton className="h-3 w-24" />
        </CardContent>
      </Card>
    );
  }
  return (
    <Card className="border border-border/60 shadow-sm">
      <CardContent className="pt-5 pb-4 px-5">
        <div className="flex items-start justify-between mb-2">
          <p className="text-xs font-medium text-muted-foreground">{title}</p>
          <span className="text-muted-foreground/60">{icon}</span>
        </div>
        <p className="text-2xl font-bold text-foreground leading-none">{value}</p>
        {sub && <p className="text-xs text-muted-foreground mt-1.5">{sub}</p>}
      </CardContent>
    </Card>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

const Reports = () => {
  const [range, setRange] = useState<RangeOption>("Last 30 days");
  const { data: stats, isLoading: statsLoading, error: statsError } = useProductivityStats();

  return (
    <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
        {/* Header */}
        <div className="flex items-start justify-between mb-6">

