1	"use client";
2	
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { useAuth } from "@/hooks/useAuth";
6	
7	const STALE_TIME = 5 * 60 * 1000; // 5 minutes
8	
9	// ─── Types ────────────────────────────────────────────────────────────────────
10	
11	export interface TimeToHireRow {
12	  job_id: string;
13	  title: string | null;
14	  job_created: string;
15	  first_hire_at: string | null;
16	  days_to_hire: number | null;
17	}
18	
19	export interface StageConversionRow {
20	  job_id: string;
21	  stage: string;
22	  count: number;
23	}
24	
25	export interface ScoreDistributionRow {
26	  bucket: string;
27	  count: number;
28	}
29	
30	export interface DailyActivityRow {
31	  activity_date: string;
32	  resumes_processed: number;
33	  jobs_active: number;
34	}
35	
36	export interface TopJobRow {
37	  job_id: string;
38	  title: string | null;
39	  candidate_count: number;
40	  avg_score: number;
41	  top_score: number;
42	}
43	
44	export interface ProductivityStats {
45	  total_jobs: number;
46	  total_candidates: number;
47	  total_credits_used: number;
48	  avg_candidates_per_job: number; // numeric (not int) — ratio can be decimal
49	  jobs_last_30_days: number;
50	  candidates_last_30_days: number;
51	}
52	
53	// Aggregated funnel: stage → total across all jobs for this user
54	export interface FunnelItem {
55	  stage: string;
56	  count: number;
57	  label: string;
58	}
59	
60	// ─── Hooks ────────────────────────────────────────────────────────────────────
61	
62	export function useTimeToHire() {
63	  const { user } = useAuth();
64	  return useQuery<TimeToHireRow[]>({
65	    queryKey: ["analytics_time_to_hire", user?.id],
66	    enabled: !!user,
67	    staleTime: STALE_TIME,
68	    queryFn: async () => {
69	      // Views now filter by auth.uid() internally (security_invoker=true).
70	      // No need for .eq("user_id", ...) — it would be redundant.
71	      const { data, error } = await (supabase as any)
72	        .from("v_time_to_hire")
73	        .select("job_id, title, job_created, first_hire_at, days_to_hire")
74	        .not("days_to_hire", "is", null)
75	        .order("job_created"); // H3: order for stable trend comparison
76	      if (error) throw new Error(error.message);
77	      return (data ?? []) as TimeToHireRow[];
78	    },
79	  });
80	}
81	
82	export function useStageConversion() {
83	  const { user } = useAuth();
84	  return useQuery<FunnelItem[]>({
85	    queryKey: ["analytics_stage_conversion", user?.id],
86	    enabled: !!user,
87	    staleTime: STALE_TIME,
88	    queryFn: async () => {
89	      const { data, error } = await (supabase as any)
90	        .from("v_stage_conversion")
91	        .select("stage, count");
92	      if (error) throw new Error(error.message);
93	
94	      const rows = (data ?? []) as StageConversionRow[];
95	
96	      // Aggregate counts across all jobs per stage
97	      const stageTotals: Record<string, number> = {};
98	      for (const row of rows) {
99	        stageTotals[row.stage] = (stageTotals[row.stage] ?? 0) + row.count;
100	      }
101	
102	      const STAGE_ORDER = [
103	        { key: "applied",   label: "Applied" },
104	        { key: "screened",  label: "Screened" },
105	        { key: "interview", label: "Interview" },
106	        { key: "offer",     label: "Offer" },
107	        { key: "hired",     label: "Hired" },
108	      ];
109	
110	      return STAGE_ORDER.map(({ key, label }) => ({
111	        stage: key,
112	        label,
113	        count: stageTotals[key] ?? 0,
114	      }));
115	    },
116	  });
117	}
118	
119	export function useScoreDistribution() {
120	  const { user } = useAuth();
121	  return useQuery<ScoreDistributionRow[]>({
122	    queryKey: ["analytics_score_distribution", user?.id],
123	    enabled: !!user,
124	    staleTime: STALE_TIME,
125	    queryFn: async () => {
126	      const { data, error } = await (supabase as any)
127	        .from("v_score_distribution")
128	        .select("bucket, count")
129	        .order("bucket");
130	      if (error) throw new Error(error.message);
131	
132	      // Ensure all 10 buckets are present even if count=0
133	      const BUCKETS = [
134	        "0-9","10-19","20-29","30-39","40-49",
135	        "50-59","60-69","70-79","80-89","90-100",
136	      ];
137	      const byBucket: Record<string, number> = {};
138	      for (const row of (data ?? []) as ScoreDistributionRow[]) {
139	        byBucket[row.bucket] = row.count;
140	      }
141	      return BUCKETS.map((b) => ({ bucket: b, count: byBucket[b] ?? 0 }));
142	    },
143	  });
144	}
145	
146	export function useDailyActivity() {
147	  const { user } = useAuth();
148	  return useQuery<DailyActivityRow[]>({
149	    queryKey: ["analytics_daily_activity", user?.id],
150	    enabled: !!user,
151	    staleTime: STALE_TIME,
152	    queryFn: async () => {
153	      const { data, error } = await (supabase as any)
154	        .from("v_daily_activity")
155	        .select("activity_date, resumes_processed, jobs_active")
156	        .order("activity_date");
157	      if (error) throw new Error(error.message);
158	      return (data ?? []) as DailyActivityRow[];
159	    },
160	  });
161	}
162	
163	export function useTopJobs() {
164	  const { user } = useAuth();
165	  return useQuery<TopJobRow[]>({
166	    queryKey: ["analytics_top_jobs", user?.id],
167	    enabled: !!user,
168	    staleTime: STALE_TIME,
169	    queryFn: async () => {
170	      const { data, error } = await (supabase as any)
171	        .from("v_top_jobs")
172	        .select("job_id, title, candidate_count, avg_score, top_score")
173	        .order("avg_score", { ascending: false })
174	        .limit(10);
175	      if (error) throw new Error(error.message);
176	      return (data ?? []) as TopJobRow[];
177	    },
178	  });
179	}
180	
181	export function useProductivityStats() {
182	  const { user } = useAuth();
183	  return useQuery<ProductivityStats>({
184	    queryKey: ["analytics_productivity", user?.id],
185	    enabled: !!user,
186	    staleTime: STALE_TIME,
187	    queryFn: async () => {
188	      // C2 fix: call with NO arguments — function now uses auth.uid() internally.
189	      const { data, error } = await (supabase as any).rpc("user_productivity_stats");
190	      if (error) throw new Error(error.message);
191	      // RPC returns an array with one row
192	      const row = Array.isArray(data) ? data[0] : data;
193	      return (row ?? {
194	        total_jobs: 0,
195	        total_candidates: 0,
196	        total_credits_used: 0,
197	        avg_candidates_per_job: 0,
198	        jobs_last_30_days: 0,
199	        candidates_last_30_days: 0,
200	      }) as ProductivityStats;
201	    },
202	  });
203	}
204

